-- Generated by n8n/build/feedback_demo.py; explicit demonstration only.
WITH up AS (
      INSERT INTO feedback (feedback_id, student_id, event_id, kind, q1_rating, q2_rating, q3_rating, composite, has_comment, submitted_at)
      SELECT f.feedback_id, f.student_id, f.event_id, f.kind, f.q1_rating, f.q2_rating, f.q3_rating, f.composite, f.has_comment, f.submitted_at FROM json_populate_recordset(NULL::feedback, $1::json->'rows') f
      WHERE EXISTS (SELECT 1 FROM students s WHERE s.student_id=f.student_id)
        AND ((f.event_id IS NULL AND f.kind IN (SELECT json_array_elements_text($1::json->'monthlyKinds')))
          OR EXISTS (SELECT 1 FROM events e WHERE e.event_id=f.event_id AND e.status='held'
             AND e.planned_for <= f.submitted_at
             AND e.kind IN (SELECT json_array_elements_text(($1::json->'kindEventMap')->f.kind))))
        AND NOT EXISTS (SELECT 1 FROM feedback old WHERE old.feedback_id<>f.feedback_id
          AND old.student_id=f.student_id
          AND ((f.event_id IS NOT NULL AND old.event_id=f.event_id)
            OR (f.event_id IS NULL AND old.event_id IS NULL AND old.kind=f.kind
              AND date_trunc('month', old.submitted_at)=date_trunc('month', f.submitted_at))))
      ON CONFLICT (feedback_id) DO UPDATE SET student_id=EXCLUDED.student_id, event_id=EXCLUDED.event_id, kind=EXCLUDED.kind, q1_rating=EXCLUDED.q1_rating, q2_rating=EXCLUDED.q2_rating, q3_rating=EXCLUDED.q3_rating, composite=EXCLUDED.composite, has_comment=EXCLUDED.has_comment, submitted_at=EXCLUDED.submitted_at
      WHERE feedback.student_id IS NOT DISTINCT FROM EXCLUDED.student_id AND feedback.event_id IS NOT DISTINCT FROM EXCLUDED.event_id AND feedback.kind IS NOT DISTINCT FROM EXCLUDED.kind AND feedback.q1_rating IS NOT DISTINCT FROM EXCLUDED.q1_rating AND feedback.q2_rating IS NOT DISTINCT FROM EXCLUDED.q2_rating AND feedback.q3_rating IS NOT DISTINCT FROM EXCLUDED.q3_rating AND feedback.composite IS NOT DISTINCT FROM EXCLUDED.composite AND feedback.has_comment IS NOT DISTINCT FROM EXCLUDED.has_comment AND feedback.submitted_at IS NOT DISTINCT FROM EXCLUDED.submitted_at
      RETURNING 1
    ) SELECT count(*)::int AS upserted FROM up;
